import { spawnSync as realSpawnSync } from 'node:child_process';
const prof = ((globalThis as any).__prof ??= { spawnMs: 0, spawns: 0 });
const spawnSync = ((...args: any[]) => { const t = performance.now(); try { return (realSpawnSync as any)(...args); } finally { prof.spawnMs += performance.now() - t; prof.spawns += 1; } }) as typeof realSpawnSync;

import { afterEach, beforeAll, describe, expect, it, vi } from 'vitest';
import { afterEach as profAfter, beforeEach as profBefore } from 'vitest';
let profSpawn = 0, profSpawns = 0, profT = 0;
profBefore(() => { const p = (globalThis as any).__prof ?? { spawnMs: 0, spawns: 0 }; profSpawn = p.spawnMs; profSpawns = p.spawns; profT = performance.now(); });
profAfter(ctx => { const p = (globalThis as any).__prof ?? { spawnMs: 0, spawns: 0 }; process.stdout.write(`PROF\t${ctx.task.suite?.name ?? ''} > ${ctx.task.name}\t${(performance.now() - profT).toFixed(0)}\t${(p.spawnMs - profSpawn).toFixed(0)}\t${p.spawns - profSpawns}\n`); });
